           if (isValidPhone(input.value) || !input.value.trim()) clearError(input);
        } else {
           if (input.value.trim()) clearError(input);
        }
      }
    });
  });

  function showError(inputElement, errorElementId) {
    inputElement.setAttribute('aria-invalid', 'true');
    const errorMsg = document.getElementById(errorElementId);
    errorMsg.removeAttribute('hidden');

    // Combine existing describedby with the error message
