        inputElement.setAttribute('aria-describedby', (currentDescribedBy + ' ' + errorElementId).trim());
    }
  }

  function clearError(inputElement) {
    inputElement.removeAttribute('aria-invalid');
    const errorElementId = inputElement.id === 'full-name' ? 'name-error' : inputElement.id + '-error';
    const errorMsg = document.getElementById(errorElementId);
    if (errorMsg) {
       errorMsg.setAttribute('hidden', '');

       // Remove error message from describedby
       const currentDescribedBy = inputElement.getAttribute('aria-describedby') || '';
       const newDescribedBy = currentDescribedBy.replace(errorElementId, '').replace(/\s+/g, ' ').trim();

       if (newDescribedBy) {
           inputElement.setAttribute('aria-describedby', newDescribedBy);
       } else {
           inputElement.removeAttribute('aria-describedby');
       }
    }
  }

  function isValidEmail(email) {
    // Basic email validation regex
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
  }

  function isValidPhone(phone) {
      // Allow digits, spaces, plus, hyphens, parentheses
      // This is a very permissive regex for international phone numbers
      const phoneRegex = /^[\d\s+\-()]+$/;
      return phoneRegex.test(phone) && phone.replace(/[^0-9]/g, '').length >= 7;
  }
